import AVFoundation
import AppKit

/// UltaMac's original sound palette (generated by scripts/make-sounds.swift, bundled in
/// Contents/Resources/Sounds). Off by default.
enum SoundEffect: String, CaseIterable, Identifiable {
    case launch, scanStart, milestone, scanComplete, found, confirm, success, warning, error, navigate
    case usbConnect, writeStart, writeComplete, verifySuccess

    var id: String { rawValue }

    var title: String {
        switch self {
        case .launch: "App launch"
        case .scanStart: "Scan started"
        case .milestone: "Scan milestone"
        case .scanComplete: "Scan complete"
        case .found: "Junk found"
        case .confirm: "Cleanup confirmed"
        case .success: "Cleanup succeeded"
        case .warning: "Warning"
        case .error: "Error"
        case .navigate: "Navigation"
        case .usbConnect: "USB connected"
        case .writeStart: "Imaging started"
        case .writeComplete: "Imaging complete"
        case .verifySuccess: "Verification passed"
        }
    }
}

@MainActor
enum Sound {
    private static var players: [SoundEffect: AVAudioPlayer] = [:]

    static var isEnabled: Bool { UserDefaults.standard.bool(forKey: "soundEnabled") }
    static var volume: Float { UserDefaults.standard.object(forKey: "soundVolume") as? Float ?? 0.6 }
    static var navigationSounds: Bool { UserDefaults.standard.bool(forKey: "soundNavigation") }

    /// Respects System Settings › Sound › "Play user interface sound effects".
    static var systemAllowsUISounds: Bool {
        let value = CFPreferencesCopyAppValue("com.apple.sound.uiaudio.enabled" as CFString, "com.apple.systemsound" as CFString)
        return (value as? Int).map { $0 != 0 } ?? true
    }

    static func play(_ effect: SoundEffect) {
        guard isEnabled, systemAllowsUISounds else { return }
        if effect == .navigate && !navigationSounds { return }
        preview(effect)
    }

    /// Plays regardless of the on/off setting (used by the Settings preview buttons).
    static func preview(_ effect: SoundEffect) {
        guard let player = player(for: effect) else { return }
        player.volume = volume
        player.currentTime = 0
        player.play()
    }

    static var isBundled: Bool { url(for: .launch) != nil }

    private static func url(for effect: SoundEffect) -> URL? {
        Bundle.main.url(forResource: effect.rawValue, withExtension: "wav", subdirectory: "Sounds")
    }

    private static func player(for effect: SoundEffect) -> AVAudioPlayer? {
        if let p = players[effect] { return p }
        guard let url = url(for: effect), let p = try? AVAudioPlayer(contentsOf: url) else { return nil }
        p.prepareToPlay()
        players[effect] = p
        return p
    }
}
